# ---------------------------------------------------------------- Excel workbook of every register
book = Workbook(); book.remove(book.active)
sheets = [("1 Architecture routes", "architecture_routes"), ("1b Tables", "architecture_tables"), ("1c DB functions", "architecture_functions"),
          ("2 Screens (111)", "screen_coverage"), ("3 Requirements V3.1", "requirements_v3_1"), ("3b Legacy v6 clauses", "requirements_legacy_v6"),
          ("4 Financial events", "financial_event_blueprint"), ("5 Integrations", "integration_feasibility"), ("6 Visual baseline", "visual_baseline"),
          ("7 Release & recovery", "release_recovery"), ("Decisions needed", "decisions_needed")]
for title, name in sheets:
    ws = book.create_sheet(title[:31]); rows = list(csv.reader(open(OUT / f"{name}.csv")))
    for r in rows: ws.append(r)
    for c in ws[1]: c.font = Font(bold=True, color="FFFFFF"); c.fill = PatternFill("solid", fgColor="223B35")
    ws.freeze_panes = "B2"
    for col in ws.columns: ws.column_dimensions[col[0].column_letter].width = min(60, max(10, max(len(str(c.value or "")) for c in col[:40]) * 0.9))
    for row in ws.iter_rows(min_row=2):
        for c in row: c.alignment = Alignment(wrap_text=True, vertical="top")
book.save(OUT / f"THAPAL_GATE1_REGISTERS_{DATE}.xlsx")
print("written:", ", ".join(n for _, n in sheets), "+ workbook")
